<script setup>definePageMeta({middleware:['auth','admin']});const {data,refresh}=await useFetch('/api/admin/users');const f=reactive({name:'',nik:'',email:'',phone:'',company:'PCI Demo'});async function add(){await $fetch('/api/admin/users',{method:'POST',body:f});Object.keys(f).forEach(k=>f[k]='');f.company='PCI Demo';refresh()}</script><template><main class="max-w-5xl mx-auto p-7"><h1 class="text-3xl font-black mb-5">Karyawan</h1><form class="panel grid md:grid-cols-5 gap-2 mb-5" @submit.prevent="add"><input v-model="f.name" class="input" placeholder="Nama" required><input v-model="f.nik" class="input" placeholder="NIK" required><input v-model="f.email" class="input" type="email" placeholder="Email" required><input v-model="f.phone" class="input" placeholder="WA"><button class="btn-primary">Daftarkan</button></form><div class="panel"><div v-for="u in data?.users" class="grid grid-cols-4 border-t py-3"><span>{{u.name}}</span><span>{{u.nik}}</span><span>{{u.email}}</span><span>{{u.status}}</span></div></div></main></template>